13	// Control-plane commands reference orgs and projects by their parent ULID in
14	// many places (repo create --project, project create --owner, grant org/project
15	// <id>, …). ULIDs are unfriendly to type, so these refs also accept a human
16	// name: looksLikeULID decides which form was given, and the resolveXRef helpers
17	// turn a name into its ULID via a list lookup. A ULID is always passed straight
18	// through with no network call, preserving the original behavior exactly.
19	
20	// looksLikeULID reports whether s has the shape of a ULID: 26 characters drawn
21	// from Crockford base32 (digits plus uppercase letters, excluding I, L, O, U).
22	// The check is shape-only and case-insensitive on the alphabet; it never hits
23	// the network. A name that happened to be 26 valid base32 characters would be
24	// misread as an id, but real org/project names don't take that form, and the
25	// user can always fall back to the explicit ULID.
26	func looksLikeULID(s string) bool {
27		if len(s) != 26 {
28			return false
29		}
30		for _, r := range strings.ToUpper(s) {
31			switch {
32			case r >= '0' && r <= '9':
33			case r >= 'A' && r <= 'Z' && r != 'I' && r != 'L' && r != 'O' && r != 'U':
34			default:
35				return false
36			}
37		}
38		return true
39	}
