41	// resolveOrgRef turns an org reference (ULID or name) into its ULID. A ULID is
42	// returned unchanged; a name is resolved by the server's exact-name lookup
43	// (GET /orgs?name=), an O(1) match that doesn't depend on the org landing on
44	// the first page of a now-paginated list.
45	func resolveOrgRef(ctx context.Context, c *coreapi.Client, ref string) (string, error) {
46		if looksLikeULID(ref) {
47			return ref, nil
48		}
49		out, err := c.ListOrgs(ctx, coreapi.ListOrgsParams{Name: coreapi.NewOptString(ref)})
50		if err != nil {
51			if isNotFound(err) {
52				return "", fmt.Errorf("no org named %q (run `entire org list` to see names, or pass a ULID)", ref)
53			}
54			return "", err
55		}
56		if !out.Org.Set {
57			return "", fmt.Errorf("no org named %q (run `entire org list` to see names, or pass a ULID)", ref)
58		}
59		return out.Org.Value.ID, nil
60	}
