62	// resolveAccountRef turns an account reference into its ULID. A ULID passes
63	// through unchanged; otherwise the ref is a provider-qualified handle (e.g.
64	// "github:alice") resolved via the control plane. We support github-backed
65	// user accounts today; other providers will resolve once they exist server-side.
66	func resolveAccountRef(ctx context.Context, c *coreapi.Client, ref string) (string, error) {
67		if looksLikeULID(ref) {
