// resolveOrgRef turns an org reference (ULID or name) into its ULID. A ULID is
// returned unchanged; a name is looked up against the caller's visible orgs,
// walking every page so a match isn't missed on a now-paginated list.
func resolveOrgRef(ctx context.Context, c *coreapi.Client, ref string) (string, error) {
	if looksLikeULID(ref) {
		return ref, nil
	}
	orgs, err := fetchAllPages(ctx, func(ctx context.Context, cursor string) ([]coreapi.Org, string, error) {
		params := coreapi.ListOrgsParams{}
		if cursor != "" {
			params.PageToken = coreapi.NewOptString(cursor)
		}
		out, err := c.ListOrgs(ctx, params)
		if err != nil {
			return nil, "", err
		}
		return out.Orgs, out.NextPageToken.Or(""), nil
	})
	if err != nil {
		return "", err
	}
	return pickOrg(orgs, ref)
}

